USE campushire;
CREATE OR REPLACE VIEW student_application_summary AS SELECT s.id student_id,s.full_name,s.roll_number,COUNT(a.id) applications,SUM(a.status='offered') offers,SUM(a.status='rejected') rejected FROM students s LEFT JOIN applications a ON a.student_id=s.id GROUP BY s.id;
CREATE OR REPLACE VIEW company_recruitment_summary AS SELECT c.id company_id,c.name,COUNT(DISTINCT i.id) internships,COUNT(a.id) applications,COUNT(o.id) offers FROM companies c LEFT JOIN internships i ON i.company_id=c.id LEFT JOIN applications a ON a.internship_id=i.id LEFT JOIN offers o ON o.application_id=a.id GROUP BY c.id;
CREATE OR REPLACE VIEW internship_application_stats AS SELECT i.id,i.title,c.name company,COUNT(a.id) applications,SUM(a.status IN ('shortlisted','interview','offered')) qualified FROM internships i JOIN companies c ON c.id=i.company_id LEFT JOIN applications a ON a.internship_id=i.id GROUP BY i.id;
CREATE OR REPLACE VIEW placement_statistics AS SELECT d.name department,COUNT(DISTINCT s.id) students,COUNT(DISTINCT a.id) applications,COUNT(DISTINCT CASE WHEN o.response='accepted' THEN o.id END) placements FROM departments d LEFT JOIN students s ON s.department_id=d.id LEFT JOIN applications a ON a.student_id=s.id LEFT JOIN offers o ON o.application_id=a.id GROUP BY d.id;
